// LoadGameServer loads the gameServerLifecycleEvent's GameServer into the .R struct
func (os GameServerLifecycleEventSlice) LoadGameServer(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	gameServers, err := os.GameServer(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.GameServer = nil
		o.R.Loaded.GameServer = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	gameServerLifecycleEventByKey := make(map[string][]*GameServerLifecycleEvent, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		gameServerLifecycleEventByKey[o.GameServerID] = append(gameServerLifecycleEventByKey[o.GameServerID], o)
	}

	for _, rel := range gameServers {

		owners, ok := gameServerLifecycleEventByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.GameServer != nil {
				continue
			}

			rel.R.GameServerLifecycleEvents = append(rel.R.GameServerLifecycleEvents, o)

			o.R.GameServer = rel

		}
	}

	return nil
}

